parameters.jsonBody:
={{ ({
  model: 'gpt-5-mini',
  store: true,
  input: [
    {
      role: 'developer',
      content: $json.classification_instructions
    },
    {
      role: 'user',
      content: $json.reply_input
    }
  ],
  text: {
    format: {
      type: 'json_schema',
      name: 'lead_intent_classification',
      strict: true,
      schema: {
        type: 'object',
        properties: {
          category: {
            type: 'string',
            description: 'Intent classification for the lead.',
            enum: ['OOO', 'Interested', 'NRR', 'Spam_Inbound', 'Left_Company', 'other']
          },
          confidence: {
            type: 'number',
            description: "Model's confidence in the classification (0-100).",
            minimum: 0,
            maximum: 100
          },
          short_reason: {
            type: 'string',
            description: 'Very short explanation (1 sentence max) of why this category was chosen.',
            minLength: 1,
            maxLength: 200
          },
          language_detected: {
            type: 'string',
            description: 'Top-level detected language code for the message.',
            enum: ['pl', 'en', 'de', 'other']
          }
        },
        required: ['category', 'confidence', 'short_reason', 'language_detected'],
        additionalProperties: false
      }
    }
  }
}) }}

={{ (() => {
  const companies = (
    $('Get contact').item.json.lead.current_experience
    ?? []
  ).map(company => ({
    name: company.name ?? '',
    universal_name: company.universal_name ?? ''
  })).filter(company => company.name || company.universal_name);

  const companyUniversalNames = [
    ...new Set(
      companies
        .map(company => company.universal_name)
        .filter(Boolean)
    )
  ];

  return {
    model: 'gpt-5-mini',
    store: true,
    input: [
      {
        role: 'developer',
        content: `You are checking whether a lead reply mentions any company from the person's current LinkedIn experience.

Rules:
- You will receive the lead reply text and a list of companies.
- Check whether the reply explicitly mentions any company from the provided list.
- If a company is mentioned, return that company's universal_name exactly as provided.
- Only return universal_name values from the provided company list.
- If no provided company is mentioned, return null.`
      },
      {
        role: 'user',
        content: JSON.stringify({
          reply_text: $('Webhook').item.json.body.event.message,
          current_experience_companies: companies
        })
      }
    ],
    text: {
      format: {
        type: 'json_schema',
        name: 'company_mention_check',
        strict: true,
        schema: {
          type: 'object',
          properties: {
            mentioned_company_universal_name: {
              type: ['string', 'null'],
              description: 'The universal_name of the current LinkedIn experience company mentioned in the reply. Return null if no provided company is mentioned.',
              enum: [...companyUniversalNames, null]
            }
          },
          required: ['mentioned_company_universal_name'],
          additionalProperties: false
        }
      }
    }
  };
})() }}
